  <script>
    // Address type selector
    function selectType(element) {
      document.querySelectorAll('.type-pill').forEach(el => el.classList.remove('active'));
      element.classList.add('active');
    }

    // Auto format phone number: 050 123 4567
    function formatPhone(input) {
      let digits = input.value.replace(/\D/g, '');
      if (digits.length > 10) digits = digits.substring(0, 10);

      let formatted = '';
      if (digits.length > 0) {
        formatted += digits.substring(0, 3);
      }
      if (digits.length >= 4) {
        formatted += ' ' + digits.substring(3, 6);
      }
      if (digits.length >= 7) {
        formatted += ' ' + digits.substring(6, 10);
      }
      input.value = formatted;
    }

    // Auto format 10-digit Makani: 12345 67890
    function formatMakani(input) {
      let digits = input.value.replace(/\D/g, '');
      if (digits.length > 10) digits = digits.substring(0, 10);

      let formatted = digits;
      if (digits.length > 5) {
        formatted = digits.substring(0, 5) + ' ' + digits.substring(5, 10);
      }
      input.value = formatted;
    }

    // Form submission handler
    function handleFormSubmit(e) {
